class Component extends DCLogic {
  state = { faq: null };

  renderVals() {

    const su = this.state.su, suMode = this.state.suMode || 'signup';
    const suSel = this.state.suPlan || TIERS[0].key;
    const suSelT = TIERS.find(t => t.key === suSel) || TIERS[0];
    const suOpenFn = (e) => { if (e && e.preventDefault) e.preventDefault(); this.setState({ su: window.DB_USER ? 'plan' : 'auth' }); };
    const suOrder = window.DB_USER && su !== 'auth' ? ['plan', 'checkout'] : ['auth', 'plan', 'checkout'];
    const suIdx = suOrder.indexOf(su);
    const suVals = {
      suOpen: !!su,
      suStepTotal: suOrder.length,
      suBar3Show: suOrder.length > 2 ? 'block' : 'none',
      suStepNum: suIdx + 1,
      suBar2: suIdx >= 1 ? 'var(--db-accent-deep)' : 'rgb(226,226,226)',
      suBar3: suIdx >= 2 ? 'var(--db-accent-deep)' : 'rgb(226,226,226)',
      suIsAuth: su === 'auth', suIsPlan: su === 'plan', suIsCheckout: su === 'checkout',
      suIsSignup: suMode === 'signup', suIsLogin: suMode === 'login',
      suAuthTitle: suMode === 'signup' ? 'Create your account' : 'Welcome back',
      suAuthCta: suMode === 'signup' ? 'Create account' : 'Sign in',
      suPwAuto: suMode === 'signup' ? 'new-password' : 'current-password',
      suTabSignupBg: suMode === 'signup' ? 'rgb(255,255,255)' : 'transparent',
      suTabLoginBg: suMode === 'login' ? 'rgb(255,255,255)' : 'transparent',
      suTabSignupShadow: suMode === 'signup' ? '0 1px 3px rgba(43,46,48,0.16)' : 'none',
      suTabLoginShadow: suMode === 'login' ? '0 1px 3px rgba(43,46,48,0.16)' : 'none',
      suToSignup: () => this.setState({ suMode: 'signup' }),
      suToLogin: () => this.setState({ suMode: 'login' }),
      suClose: () => this.setState({ su: null }),
      suNext: (e) => { if (e && e.preventDefault) e.preventDefault(); this.setState(s => ({ su: suOrder[Math.min(suOrder.indexOf(s.su) + 1, suOrder.length - 1)] })); },
      suBack: () => this.setState(s => (suOrder.indexOf(s.su) <= 0 ? { su: null } : { su: suOrder[suOrder.indexOf(s.su) - 1] })),
      suPlans: TIERS.map(t => {
        const on = t.key === suSel;
        const note = t.term === 'yearly' && t.yearlyTotal ? 'Save $' + (t.monthly * 12 - t.yearlyTotal).toFixed(2).replace(/\.00$/, '') + ' vs. monthly' : '';
        return { name: t.name, badge: t.badge, price: t.price, note, on,
          border: on ? '2px solid var(--db-accent-deep)' : '1px solid rgb(214,214,214)',
          bg: on ? 'rgba(15,128,121,0.05)' : 'rgb(255,255,255)',
          dotBorder: on ? '6px solid var(--db-accent-deep)' : '2px solid rgb(170,170,170)',
          pick: () => this.setState({ suPlan: t.key }) };
      }),
      suSelName: suSelT.name, suSelPrice: suSelT.price,
      heroCtaProps: { ...CTA('var(--db-orange-300)'), onClick: suOpenFn },
      signupCtaProps: { ...CTA('var(--db-accent-deep)'), onClick: suOpenFn }
    };
    const faq = {};
    ['faq1', 'faq2', 'faq3', 'faq4', 'faq5'].forEach(k => {
      const isOpen = this.state.faq === k;
      faq[k + 'Open'] = isOpen;
      faq[k + 'Sign'] = isOpen ? '\u2212' : '+';
      faq[k + 'Toggle'] = () => this.setState(s => ({ faq: s.faq === k ? null : k }));
    });


    const byId = id => P.find(p => p.id === id);
    const launchIds = ['PR00001380','PR00001397','6095538','P5258117','P5197705','P5183500','P5043081','P5068623','6017019','P3941679'];
    const launches = launchIds.map(id => byId(id)).filter(Boolean).map(p => ({ t: p.t, by: p.by, href: '#/p/' + p.id, coverStyle: { display: 'block', width: '100%', aspectRatio: '3 / 4', borderRadius: '2px', backgroundImage: 'url(' + p.img[0] + ')', backgroundSize: 'contain', backgroundPosition: 'left center', backgroundRepeat: 'no-repeat' } }));
    return {
      ...faq,
      launches,
      ...suVals,
      tiers: TIERS.map(t => {
        const money = v => '$' + v.toFixed(2).replace(/\.00$/, '');
        let compare = '', save = '', annual = '';
        if (t.term === 'monthly') {
          annual = money(t.monthly * 12) + '/year total';
        } else if (t.term === 'yearly') {
          compare = money(t.monthly * 12) + '/year';
          save = 'Save ' + money(t.monthly * 12 - t.yearlyTotal);
        }
        const price = t.price;
        const slash = price.indexOf('/');
        const accent = 'var(--db-accent-deep)';
        const hairline = 'var(--db-accent)';
        return {
          name: t.name,
          nameColor: accent,
          cardProps: {
            ground: 'white',
            padding: 'none',
            style: {
              position: 'relative',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              padding: 'clamp(18px, 3vw, 28px)',
              borderColor: hairline
            }
          },
          amount: slash === -1 ? price : price.slice(0, slash),
          unit: slash === -1 ? '' : price.slice(slash),
          unitSize: '16px',
          amountSize: '38px',
          rowWhite: t.term ? 'nowrap' : 'normal',
          rowMargin: t.term ? 'clamp(6px, 1.8vw, 20px) -16px 0' : 'clamp(6px, 1.8vw, 20px) 0 0',
          compare,
          save,
          annual,
          badge: t.badge,
          hasMeta: !!(compare || save || annual)
        };
      }),

    };
  }
}

